// Step 1: Analyze Clarification Context
const input = $input.first().json;

const userId = input.user_id;
const action = input.clarification_action || (input.pending_clarification ? 'resolve' : 'create');
const questionText = input.question_text || (input.clarification_questions && input.clarification_questions[0]) || '¿Podrías especificar a qué te refieres?';
const questionType = input.question_type || 'entity_disambiguation';
const answerText = input.text || input.answer_text;
const clarificationId = (input.pending_clarification && input.pending_clarification.id) || input.clarification_id;

return [{
  json: {
    ...input,
    user_id: userId,
    clarification_action: action,
    clarification_id: clarificationId,
    question_text: questionText,
    question_type: questionType,
    answer_text: answerText
  }
}];

const req = $('Prepare Clarification Action').first().json;
const resRaw = $input.first().json.clar_res;

let responseText = '';
if (req.clarification_action === 'create') {
  responseText = req.question_text;
} else {
  responseText = '¡Perfecto, ya lo registré correctamente!';
}

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      action: req.clarification_action,
      clarification_id: resRaw || req.clarification_id,
      response_text: responseText
    }
  }
}];
